69	ACL9Monster::ACL9Monster()
70	{
71		PrimaryActorTick.bCanEverTick = true;
72		SetReplicateMovement(true);
73		Kind = ECL9ActorKind::Monster;
74	
75		// 벽(WorldStatic)은 막지만, 폰·아이템·다른 몬스터는 서로 겹쳐 지나간다 —
76		// 복도의 위협은 몸으로 막는 게 아니라 발각이다 (2026-09-03 결정).
77		SphereComponent = CreateDefaultSubobject<USphereComponent>(TEXT("Sphere"));
78		SphereComponent->SetCollisionEnabled(ECollisionEnabled::QueryOnly);
79		SphereComponent->SetCollisionObjectType(ECC_WorldDynamic);
80		SphereComponent->SetCollisionResponseToAllChannels(ECR_Overlap);
81		SphereComponent->SetCollisionResponseToChannel(ECC_WorldStatic, ECR_Block);
82		SphereComponent->SetCollisionResponseToChannel(ECC_Camera, ECR_Ignore);
83		SetRootComponent(SphereComponent);
84	
85		MeshComponent = CreateDefaultSubobject<USkeletalMeshComponent>(TEXT("Mesh"));
86		MeshComponent->SetupAttachment(SphereComponent);
87		MeshComponent->SetCollisionEnabled(ECollisionEnabled::NoCollision);
88	
89		// 처형 카메라 — 잠들어 있다가 Execute 에서만 켜진다(ApplyState). 소켓·오프셋은 행 값이라 여기서는 자리만 만든다
90		ExecuteCamera = CreateDefaultSubobject<UCameraComponent>(TEXT("ExecuteCamera"));
91		ExecuteCamera->SetupAttachment(MeshComponent);
92		ExecuteCamera->bAutoActivate = false;
93		ExecuteCamera->SetActive(false);
94	}
