120	void ACL9Monster::LoadData()
121	{
122		const UCL9GameInstance* GameInstance = GetGameInstance<UCL9GameInstance>();
123		const UCL9DefRegistry* Registry = GameInstance ? GameInstance->GetDefRegistry() : nullptr;
124		const UCL9MonsterDef* Def = Registry ? Registry->FindMonster(GetAlias(), GetSubAlias()) : nullptr;
125	
126		if (Def == nullptr)
127		{
128			UE_LOG(LogCL9, Error, TEXT("'%s': monster row '%s'/'%s' is missing or broken — visuals stay stale (docs/data/schema.md 로드 검사)."),
129				*GetNameSafe(this), *GetAlias().ToString(), *GetSubAlias().ToString());
130			return;
131		}
132		MonsterDef = Def;
133	
134		SphereComponent->SetSphereRadius(Def->Radius);
135		MeshComponent->SetRelativeLocation(FVector(0.f, 0.f, -Def->Radius));
136		// 액터가 정면을 보게 한다 — 팩의 모델 축은 행 값으로 보정된다
137		MeshComponent->SetRelativeRotation(FRotator(0.f, Def->MeshYawOffset, 0.f));
138	
139		if (USkeletalMesh* Mesh = Def->SkeletalMesh.LoadSynchronous())
140		{
141			MeshComponent->SetSkeletalMesh(Mesh);
142		}
143		if (UClass* AnimClass = Def->AnimBP.LoadSynchronous())
144		{
145			MeshComponent->SetAnimInstanceClass(AnimClass);
146		}
147	
148		for (UCL9Gimmick* Gimmick : Def->Gimmicks)
149		{
150			if (Gimmick != nullptr)
151			{
152				Gimmick->OnActorLoaded(this);
153			}
154		}
155	
156		// 개체별 HP는 호스트에서 한 번만 굴린다 (conventions § 4)
157		if (HasAuthority() && Hp == 0)
158		{
159			Hp = FMath::RandRange(Def->HpMin, Def->HpMax);
160	
161			// 잠 많은 종(거위)은 잠든 채로 시작한다 — 맵 스포너가 나중에(⑤) 이를 덮어쓸 수 있다
162			if (Def->SleepTime > 0.f)
163			{
164				EnterState(ECL9MonsterState::Asleep);
165			}
166		}
167	}
