174	void ACL9Monster::Tick(float DeltaSeconds)
175	{
176		Super::Tick(DeltaSeconds);
177	
178		// 타격 플래시·소리·퍼프·히트스톱·전이 소리는 호스트와 클라 모두에서 같은 복제 시계로 굴러간다 — 아래 호스트 분기가 먼저
179		// 돌아가 버리기 전에 부른다
180		TickHitFlash();
181		TickHitFeel();
182		TickStateSounds();
183	
184		if (HasAuthority())
185		{
186			const FVector Before = GetActorLocation();
187			HostTickDeathLaunch(DeltaSeconds);
188			HostTickAI(DeltaSeconds);
189			DisplaySpeed = (GetActorLocation() - Before).Size2D() / FMath::Max(DeltaSeconds, UE_KINDA_SMALL_NUMBER);
190			TickFootstep();
191			return;
192		}
193	
194		// 일반 액터는 20Hz 이동 복제로 인해 위치가 툭툭 튄다 — 대신 시각 메시가
195		// 루트를 뒤쫓아가게 해서 클라이언트에게 매끄러운 움직임으로 보이게 한다
196		// (docs/systems/monster.md 3c).
197		if (!bSmoothingInitialized)
198		{
199			SmoothedLocation = GetActorLocation();
200			SmoothedRotation = GetActorRotation();
201			bSmoothingInitialized = true;
202		}
203		const FVector PreviousSmoothed = SmoothedLocation;
204		if (State == ECL9MonsterState::Execute)
205		{
206			// 처형은 텔레포트로 시작한다 — 보간하면 메시가 앵커까지 미끄러져 가는 동안 카메라가 흔들리고 피해자 옆이 빈다. 처형 동안은
207			// 스무딩을 멈추고 액터 값에 붙인다 (D1)
208			SmoothedLocation = GetActorLocation();
209			SmoothedRotation = GetActorRotation();
210		}
211		else
212		{
213			SmoothedLocation = FMath::VInterpTo(SmoothedLocation, GetActorLocation(), DeltaSeconds, SmoothingInterpSpeed);
214			SmoothedRotation = FMath::RInterpTo(SmoothedRotation, GetActorRotation(), DeltaSeconds, SmoothingInterpSpeed);
215		}
216		DisplaySpeed = (SmoothedLocation - PreviousSmoothed).Size2D() / FMath::Max(DeltaSeconds, UE_KINDA_SMALL_NUMBER);
217	
218		const float MeshZ = MonsterDef ? -MonsterDef->Radius : 0.f;
219		const float YawOffset = MonsterDef ? MonsterDef->MeshYawOffset : 0.f;
220		MeshComponent->SetWorldLocationAndRotation(SmoothedLocation + FVector(0.f, 0.f, MeshZ), SmoothedRotation + FRotator(0.f, YawOffset, 0.f));
221		TickFootstep();
222	}
