457	void ACL9Monster::HostTickAI(float DeltaSeconds)
458	{
459		if (MonsterDef == nullptr || State == ECL9MonsterState::Dead)
460		{
461			return;
462		}
463	
464		ChaseCooldownRemaining = FMath::Max(ChaseCooldownRemaining - DeltaSeconds, 0.f);
465		CatchCooldownRemaining = FMath::Max(CatchCooldownRemaining - DeltaSeconds, 0.f);
466		AlertCooldownRemaining = FMath::Max(AlertCooldownRemaining - DeltaSeconds, 0.f);
467		// 헛침 쿨다운은 여기서만, 틱당 한 번 줄어든다 — 상태 분기 안에서 다시 빼지 않는다
468		PounceMissRemaining = FMath::Max(PounceMissRemaining - DeltaSeconds, 0.f);
469	
470		HostTickProxNoise(DeltaSeconds);
471	
472		// 분노는 지속되는 동안 게이지를 고정한다 — 죽음의 비명 이후의 사냥 모드는
473		// ChaseCooldown을 우회하며 일찍 가라앉는 법이 없다 (docs/systems/monster.md 경보).
474		if (RageRemaining > 0.f)
475		{
476			RageRemaining -= DeltaSeconds;
477			DetectGauge = 1.f;
478		}
479	
480		// 수면, 기상 예고, 스턴 상태에서는 감각이 작동하지 않는다. 잡기 예고 동안도 멈춘다 — 타깃은 진입 때 잠근 PounceTarget 이고
481		// 감각의 재타깃팅은 예고 동안 무시한다(덮침은 그 타깃의 지금 위치로). 처형 중도 같다 — 타깃은 ExecuteTarget 이다
482		const bool bSensesAwake = State != ECL9MonsterState::Asleep
483			&& State != ECL9MonsterState::WakeTelegraph
484			&& State != ECL9MonsterState::Stun
485			&& State != ECL9MonsterState::Pounce
486			&& State != ECL9MonsterState::Execute;
487		if (bSensesAwake)
488		{
489			SenseTick(DeltaSeconds);
490		}
491	
492		const bool bAlertGateOpen = ChaseCooldownRemaining <= 0.f || RageRemaining > 0.f;
493	
494		switch (State)
495		{
496		case ECL9MonsterState::Asleep:
497		{
498			// 기상 트리거: WakeRadius 안에서 걷는 것(걷기는 조용하다는 예외 규칙),
499			// HearRunRadius 안에서 달리는 것, 혹은 대기 중인 경보 지점.
500			bool bTriggered = PendingInvestigateSpot.IsSet();
501			for (TActorIterator<ACL9Character> It(GetWorld()); !bTriggered && It; ++It)
502			{
503				const ACL9Character* Candidate = *It;
504				if (Candidate->IsDead())
505				{
506					continue;
507				}
508				const float Distance = FVector::Dist2D(GetActorLocation(), Candidate->GetActorLocation());
509				const float Speed = Candidate->GetVelocity().Size2D();
510				const bool bWalkWake = MonsterDef->WakeRadius > 0.f && Distance <= MonsterDef->WakeRadius && Speed > WakeMoveMinSpeed;
511				const bool bRunWake = MonsterDef->HearRunRadius > 0.f && Distance <= MonsterDef->HearRunRadius
512					&& Candidate->GetCL9CharacterMovement()->IsRunning();
513				bTriggered = bWalkWake || bRunWake;
514			}
515	
516			WakeRetryRemaining = FMath::Max(WakeRetryRemaining - DeltaSeconds, 0.f);

600		{
601			if (bHadSight && SensedCharacter.IsValid() && bAlertGateOpen)
602			{
603				EnterState(GetHuntState());
604				break;
605			}
606	
607			if (PathPoints.Num() > 0)
608			{
609				if (MoveAlongPath(DeltaSeconds, MonsterDef->PatrolSpeed))
610				{
611					PathPoints.Reset();
612					SearchDwellRemaining = MonsterDef->SearchDwellTime;
613				}
614			}
615			else
616			{
617				SearchDwellRemaining -= DeltaSeconds;
618				if (SearchDwellRemaining <= 0.f)
619				{
620					if (SearchHopsRemaining <= 0)
621					{
622						EnterState(ECL9MonsterState::Return);
623						break;
624					}
625					--SearchHopsRemaining;
626					UNavigationSystemV1* NavSystem = UNavigationSystemV1::GetCurrent(GetWorld());
627					FNavLocation Hop;
628					if (NavSystem != nullptr && NavSystem->GetRandomReachablePointInRadius(LastSensedLocation, SearchHopRadius, Hop))
629					{
630						StartPathTo(Hop.Location);
631					}
632					else
633					{
634						SearchDwellRemaining = MonsterDef->SearchDwellTime;
635					}
636				}
637			}
638			break;
639		}
640	
641		case ECL9MonsterState::Chase:
642		{
643			ACL9Character* Target = SensedCharacter.Get();
644			if (TickChaseGiveUp(Target, DeltaSeconds))
645			{
646				EnterState(ECL9MonsterState::Break);
647				break;
648			}
649	
650			// 경보를 울리는 개체는 경보가 발동하기 전 멈춰 서서 운다 (거위 AlertWindup)
651			if (AlertWindupRemaining > 0.f)
652			{
653				AlertWindupRemaining -= DeltaSeconds;
654				if (AlertWindupRemaining <= 0.f)
655				{
656					FirePackAlarm();
657					bPackAlarmFired = true;
658					AlertCooldownRemaining = MonsterDef->AlertCooldown;
659				}
660				break;
661			}
662	
663			// 잡기: 잡는 종(CatchRadius > 0)이고 KillCooldown이 다 재충전됐을 때. 넘어져 있는 타깃은 잡지도 예고하지도 않는다 —
664			// 넘어진 동안은 무적(2026-09-20 사용자)이라 진입 검사에서 건너뛰고, 추격 자체(예산·놓침·경로)는 그대로 이어져 일어나는
665			// 순간 다시 예고가 시작된다(타깃 선택에서 빼면 동료에게 튀거나 시야를 잃어 추격이 끊긴다). 처형 중인 타깃도 같다 (D3)
666			const float TargetDistance = FVector::Dist2D(GetActorLocation(), Target->GetActorLocation());
667			const bool bCanCatch = MonsterDef->CatchRadius > 0.f && CatchCooldownRemaining <= 0.f && !Target->IsKnockedDown() && !Target->IsExecuted();
668			if (bCanCatch)
669			{
670				// 예고가 켜진 종(PounceWindup > 0)은 PounceRadius 에서 멈춰 예고한다(헛친 뒤 PounceMissCooldown 동안은 다시 예고하지 않음);
671				// 꺼진 종은 옛 규칙 그대로 CatchRadius 에서 즉시 잡는다
672				if (MonsterDef->PounceWindup > 0.f)
673				{
674					if (TargetDistance <= MonsterDef->PounceRadius && PounceMissRemaining <= 0.f)
675					{
676						PounceTarget = Target;
677						EnterState(ECL9MonsterState::Pounce);
678						break;
679					}
680				}
681				else if (TargetDistance <= MonsterDef->CatchRadius)
682				{
683					HostCatch(*Target);
684					break;
685				}
686			}
687	
688			ChaseRepathRemaining -= DeltaSeconds;
689			if (ChaseRepathRemaining <= 0.f || PathPoints.Num() == 0)
690			{
691				ChaseRepathRemaining = ChaseRepathInterval;
692				StartPathTo(Target->GetActorLocation());
693			}
694			MoveAlongPath(DeltaSeconds, MonsterDef->ChaseSpeed);
695			break;
696		}
697	
698		case ECL9MonsterState::Pounce:
699		{
700			// Chase 의 부분 상태 — 탈출 조건(타깃 소실·사망·예산·놓침·HomeRange·Deaggro)을 덮치기 전에 먼저 평가한다.
701			// 타깃은 진입 때 잠근 PounceTarget 이다(접속 끊김이면 null → 놓침 규칙으로 Break)
702			ACL9Character* Target = PounceTarget.Get();
703			if (TickChaseGiveUp(Target, DeltaSeconds))
704			{
705				EnterState(ECL9MonsterState::Break);
706				break;
707			}
708	
709			// 제자리에서 타깃을 향해 돈다 — MoveAlongPath 의 회전 저항을 우회하므로 TurnRate 로만 제한한다(홱 돌지 않게)

952	void ACL9Monster::SenseTick(float DeltaSeconds)
953	{
954		// 입력 세 가지, 게이지 하나 (docs/systems/monster.md 감각 파이프라인):
955		// 히스테리시스가 있는 시야, 행동 테이블의 달리기 소음, 근접도.
956		ACL9Character* Best = nullptr;
957		float BestDistance = TNumericLimits<float>::Max();
958		bool bBestBySight = false;
959	
960		for (TActorIterator<ACL9Character> It(GetWorld()); It; ++It)
961		{
962			ACL9Character* Candidate = *It;
963			// 죽은 사람과 처형 중인 사람은 타깃이 아니다 — 둘째 몬스터가 처형 중인 피해자를 넘어뜨려 넘어짐 무적으로 "구해" 주면 안 된다 (D3)
964			if (Candidate->IsDead() || Candidate->IsExecuted())
965			{
966				continue;
967			}
968			const float Distance = FVector::Dist2D(GetActorLocation(), Candidate->GetActorLocation());
969	
970			const float SightRange = (bHadSight ? MonsterDef->SightOut : MonsterDef->SightIn) * GetDangerScale();
971			const bool bInSight = Distance <= SightRange && HasLineOfSight(*Candidate);
972	
973			bool bHeard = false;
974			if (const UCL9GameInstance* GameInstance = GetGameInstance<UCL9GameInstance>())
975			{
976				const UCL9RulesDef* Rules = GameInstance->GetDefRegistry() ? GameInstance->GetDefRegistry()->GetRules() : nullptr;
977				// 걷기는 어그로 0 — 소리는 달릴 때만 실린다 (docs/plan/data/rules.md 소리)
978				bHeard = Rules != nullptr
979					&& Distance <= Rules->RunNoiseRadius
980					&& Candidate->GetCL9CharacterMovement()->IsRunning();
981			}
982	
983			if ((bInSight || bHeard) && Distance < BestDistance)
984			{
985				Best = Candidate;
986				BestDistance = Distance;
987				bBestBySight = bInSight;
988			}
989		}
990	
991		if (Best != nullptr)
992		{
993			SensedCharacter = Best;
994			LastSensedLocation = Best->GetActorLocation();
995			bHadSight = bBestBySight;
996			SightGraceRemaining = MonsterDef->DetectGrace;
997	
998			const float Rate = (BestDistance <= MonsterDef->DetectNearRadius ? MonsterDef->DetectRateNear : MonsterDef->DetectRateFar) * GetDangerScale();
999			DetectGauge = FMath::Min(DetectGauge + Rate * DeltaSeconds, 1.f);
1000		}
1001		else
1002		{
1003			bHadSight = false;
1004			SightGraceRemaining -= DeltaSeconds;
1005			if (SightGraceRemaining <= 0.f)
1006			{
1007				DetectGauge = FMath::Max(DetectGauge - MonsterDef->DetectDecay * DeltaSeconds, 0.f);
1008			}
1009		}
1010	}
