1173	bool ACL9Monster::MoveAlongPath(float DeltaSeconds, float Speed)
1174	{
1175		if (!PathPoints.IsValidIndex(PathIndex))
1176		{
1177			return true;
1178		}
1179	
1180		FVector ToTarget = PathPoints[PathIndex] - GetActorLocation();
1181		ToTarget.Z = 0.f;
1182		if (ToTarget.Size() < WaypointTolerance)
1183		{
1184			++PathIndex;
1185			return !PathPoints.IsValidIndex(PathIndex);
1186		}
1187	
1188		// 회전 모델: 진행 방향이 TurnRate 아래에서 목표를 뒤쫓아가고, 남은 회전각이
1189		// 클수록 더 느려진다(TurnDrag) — 코너가 시간을 벌어주는 이유다.
1190		const float DesiredYaw = ToTarget.Rotation().Yaw;
1191		HeadingYaw = FMath::FixedTurn(HeadingYaw, DesiredYaw, MonsterDef->TurnRate * DeltaSeconds);
1192		const float RemainingTurn = FMath::Abs(FMath::FindDeltaAngleDegrees(HeadingYaw, DesiredYaw));
1193		const float DragScale = 1.f - MonsterDef->TurnDrag * FMath::Clamp(RemainingTurn / 90.f, 0.f, 1.f);
1194	
1195		const FVector Step = FRotator(0.f, HeadingYaw, 0.f).Vector() * Speed * FMath::Max(DragScale, 0.1f) * DeltaSeconds;
1196		FHitResult Hit;
1197		AddActorWorldOffset(Step, true, &Hit);
1198		SetActorRotation(FRotator(0.f, HeadingYaw, 0.f));
1199	
1200		if (Hit.bBlockingHit)
1201		{
1202			// 경로가 놓친 무언가에 끼여 버렸다 — 다음 틱에 다시 경로를 짠다
1203			PathPoints.Reset();
1204			return true;
1205		}
1206		return false;
1207	}
