1579	void ACL9Monster::HostTickProxNoise(float DeltaSeconds)
1580	{
1581		// 잠든 계열(Asleep·WakeTelegraph)은 소나를 내지 않는다 — 잠든 닭까지 자기 자리를 알려 주면 기상 예고로
1582		// 배우던 것이 값싸진다 (2026-09-16 사용자). 깨어 있는 상태(순찰·조사·추격…)만 낸다. Dead는 HostTickAI가 먼저 거른다.
1583		if (State == ECL9MonsterState::Asleep || State == ECL9MonsterState::WakeTelegraph)
1584		{
1585			return;
1586		}
1587	
1588		const UCL9GameInstance* GameInstance = GetGameInstance<UCL9GameInstance>();
1589		const UCL9WaveTable* Table = GameInstance != nullptr ? GameInstance->GetWaveTable() : nullptr;
1590		const FCL9WaveInfo* Row = Table != nullptr ? Table->FindRow(ECL9NoiseSource::MonsterProx) : nullptr;
1591		// 반복 간격이 없으면 근접 소나는 울리지 않는다 — 이 행은 반복으로만 나는 소음원이다
1592		if (Row == nullptr || Row->RepeatInterval <= 0.f)
1593		{
1594			return;
1595		}
1596	
1597		ProxNoiseRemaining -= DeltaSeconds;
1598		if (ProxNoiseRemaining > 0.f)
1599		{
1600			return;
1601		}
1602		ProxNoiseRemaining = Row->RepeatInterval;
1603	
1604		// TriggerRadius 안에 산 플레이어가 있을 때만 — 0이면 조건 없음
1605		if (Row->TriggerRadius > 0.f)
1606		{
1607			bool bPlayerNear = false;
1608			for (TActorIterator<ACL9Character> It(GetWorld()); It; ++It)
1609			{
1610				const ACL9Character* Candidate = *It;
1611				if (!Candidate->IsDead() && FVector::Dist2D(GetActorLocation(), Candidate->GetActorLocation()) <= Row->TriggerRadius)
1612				{
1613					bPlayerNear = true;
1614					break;
1615				}
1616			}
1617			if (!bPlayerNear)
1618			{
1619				return;
1620			}
1621		}
1622	
1623		if (ACL9GameState* GameState = GetWorld()->GetGameState<ACL9GameState>())
1624		{
1625			// 판정 반경이 없는 소음원이다 — 링 크기는 표의 FallbackRadius가 정하고, 몬스터 청각은 이 사건을 듣지 않는다
1626			GameState->HostReportNoise(ECL9NoiseSource::MonsterProx, GetActorLocation(), 0.f, this);
1627		}
1628	}
