1654	void ACL9Monster::ReceivePackAlarm(const FVector& AlarmLocation)
1655	{
1656		if (!HasAuthority() || MonsterDef == nullptr)
1657		{
1658			return;
1659		}
1660	
1661		switch (State)
1662		{
1663		case ECL9MonsterState::Asleep:
1664			PendingInvestigateSpot = AlarmLocation;
1665			break;
1666		case ECL9MonsterState::Wander:
1667		case ECL9MonsterState::Patrol:
1668		case ECL9MonsterState::Return:
1669			// 경보는 새 경계 — ChaseCooldown이 여전히 이를 막는 문턱으로 작동한다 (docs/systems/monster.md)
1670			if (ChaseCooldownRemaining <= 0.f)
1671			{
1672				LastSensedLocation = AlarmLocation;
1673				EnterState(ECL9MonsterState::Investigate);
1674			}
1675			break;
1676		case ECL9MonsterState::Stalk:
1677			// 무리가 울면 몰래 다가갈 이유가 없다 — 격분해 그대로 추격 (D4)
1678			EnterState(ECL9MonsterState::Chase);
1679			break;
1680		default:
1681			break;
1682		}
1683	}
