1692		RageRemaining = FMath::Max(RageRemaining, HuntSeconds);
1693		DetectGauge = 1.f;
1694		LastSensedLocation = DeathLocation;
1695	
1696		switch (State)
1697		{
1698		case ECL9MonsterState::Asleep:
1699			PendingInvestigateSpot = DeathLocation;
1700			break;
1701		case ECL9MonsterState::Wander:
1702		case ECL9MonsterState::Patrol:
1703		case ECL9MonsterState::Return:
