1775	void ACL9Monster::ApplyState()
1776	{
1777		// 이제 AnimBP가 복제된 상태에 따라 이동/피격/공격/사망 애니메이션을 전환한다
1778		// (docs/systems/animation.md); 여기서의 표현 처리는 행 값에 따른 메시 방향
1779		// 보정과 처형 카메라의 켜고 끔이다.
1780		if (MeshComponent != nullptr)
1781		{
1782			const float YawOffset = MonsterDef ? MonsterDef->MeshYawOffset : 0.f;
1783			MeshComponent->SetRelativeRotation(FRotator(0.f, YawOffset, 0.f));
1784		}
1785	
1786		// 처형 카메라: Execute 에서만 켠다 — 호스트는 EnterState, 클라는 OnRep_State 로 같은 자리에 온다 (D6). 소켓은 행 값
1787		// (본 이름 허용) — 있으면 그 본의 소켓 공간, **없으면 액터 루트(구 콜리전)에 액터 공간**으로 붙는다: 메시는 `MeshYawOffset`
1788		// 만큼 돌아 있고 `Radius` 만큼 내려가 있어 메시 루트 기준 오프셋은 종마다 축이 달라진다(2026-09-20 돼지 "뒷다리 사이" 사고).
1789		// 액터 공간이면 표의 `ExecuteCameraOffset` 이 "X = 전방(타깃 쪽)·Z = 위" 그대로 읽힌다. 처형 밖에서는 꺼져 있다
1790		if (ExecuteCamera != nullptr && MeshComponent != nullptr)
1791		{
1792			const bool bExecute = State == ECL9MonsterState::Execute;
1793			if (bExecute && MonsterDef != nullptr)
1794			{
1795				const bool bSocket = MeshComponent->DoesSocketExist(MonsterDef->ExecuteCameraSocket);
1796				USceneComponent* Parent = bSocket ? static_cast<USceneComponent*>(MeshComponent) : GetRootComponent();
1797				ExecuteCamera->AttachToComponent(Parent, FAttachmentTransformRules::KeepRelativeTransform, bSocket ? MonsterDef->ExecuteCameraSocket : NAME_None);
1798				ExecuteCamera->SetRelativeLocationAndRotation(MonsterDef->ExecuteCameraOffset, MonsterDef->ExecuteCameraRotation);
1799			}
1800			if (ExecuteCamera->IsActive() != bExecute)
1801			{
1802				ExecuteCamera->SetActive(bExecute);
1803			}
1804		}
1805	}
